'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const euro=n=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'}).format(n);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const cats={normal:{name:'De toda la vida',emoji:'🍝',class:'normal'},saludable:{name:'Saludable',emoji:'🥦',class:'healthy'},vegana:{name:'Vegana',emoji:'🌿',class:'vegan'},'sin-gluten':{name:'Sin gluten',emoji:'🌾',class:'gf'}};
const state={recipes:[],prices:{},ratings:{},user:null,csrf:'',favorites:new Set(),completed:new Set(),plan:null,cat:'todos',sort:'price',search:'',onlyFav:false,active:null,servings:2,step:0,authMode:'login',registrationOpen:false,selectedStore:'consum',timer:null,remaining:0,timerEnd:0,checked:new Set(),customs:{},pantry:{},shoppingStore:'consum',buyIndex:-1,plateIngredients:new Set(),plateType:'todos',plateStrict:false,fridge:{}};
const el=(id)=>document.getElementById(id);
function toast(msg){const t=el('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500)}
async function api(path,body){const opts=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body:JSON.stringify(body)};const r=await fetch(path,opts);let v;try{v=await r.json()}catch{throw Error('El servidor no responde. Abre MIGA desde su dirección web, no desde un archivo.')};if(!r.ok)throw Error(v.error||'Ha ocurrido un error.');return v}
async function initialize(){try{const [data,auth,ratings]=await Promise.all([api('/api/data'),api('/api/bootstrap'),api('/api/ratings')]);state.recipes=data.recipes;state.prices=data.prices;state.ratings=Object.fromEntries(ratings.ratings.map(r=>[r.recipe_id,r]));hydrate(auth);let local=null;try{local=JSON.parse(localStorage.getItem('miga_plan'))}catch{};state.plan=normalizePlan(auth.plan||(local&&Array.isArray(local.ids)?local:null));loadLocalPrefs();renderCards();renderPriceTable();if(state.plan){renderPlan();renderShopping()}renderPlateBuilder();if(typeof renderFeaturedRecipe==='function')renderFeaturedRecipe();navigate(location.hash.slice(1)||'inicio');}catch(e){el('recipeGrid').innerHTML=`<div class="empty error">No se puede cargar la web: ${escapeHtml(e.message)}<br><small>Comprueba que el servidor de MIGA esté en funcionamiento</small></div>`;toast(e.message)}}
function hydrate(d){state.csrf=d.csrf??state.csrf;if(typeof d.registrationOpen==='boolean')state.registrationOpen=d.registrationOpen;state.user=d.user||null;state.favorites=new Set(d.favorites||[]);state.completed=new Set(d.completed||[]);state.customs=d.user?(d.customizations||{}):loadLocal('miga_guest_customs',{});state.pantry=loadLocal('miga_pantry_'+(d.user?.id||'guest'),{});state.fridge=d.user?(d.pantryItems||{}):loadLocal('miga_fridge_guest',{});el('accountButton').innerHTML=state.user?`${escapeHtml(state.user.name.split(' ')[0])} <span>♙</span>`:'Entrar / Registro <span>👤</span>';el('adminNav').hidden=!(state.user?.role==='admin');}
function navigate(page){if(!['inicio','menu','nevera','crear','compra','precios','contacto','admin'].includes(page))page='inicio';if(page==='admin'&&state.user?.role!=='admin')page='inicio';$$('.page').forEach(v=>v.hidden=(v.id!=='page-'+page));$$('.nav-link').forEach(v=>v.classList.toggle('active',v.dataset.page===page));document.body.classList.remove('menu-open');history.replaceState(null,'','#'+page);window.scrollTo({top:0,behavior:'smooth'});if(page==='admin')renderAdmin();if(page==='compra')renderShopping();if(page==='menu'&&state.plan)renderPlan();if(page==='crear')renderPlateBuilder();if(page==='nevera'&&typeof renderFridge==='function')renderFridge();if(typeof updateMigaDashboard==='function')updateMigaDashboard()}
function loadLocal(key,defaultVal){try{const v=JSON.parse(localStorage.getItem(key));return v&&typeof v==='object'?v:defaultVal}catch{return defaultVal}}
function loadLocalPrefs(){state.pantry=loadLocal('miga_pantry_'+(state.user?.id||'guest'),{});if(!state.user)state.customs=loadLocal('miga_guest_customs',{})}
const substitutes={arroz:['pasta_sg','pasta','patata'],pasta:['pasta_sg','arroz'],pasta_sg:['arroz','pasta'],fideos:['pasta_sg','arroz'],pollo:['pavo','garbanzos','merluza'],pavo:['pollo','garbanzos'],merluza:['pollo','pavo'],atun:['pollo','garbanzos'],patata:['arroz','calabacin','zanahoria'],cebolla:['calabacin','pimiento','zanahoria'],ajo:['cebolla'],garbanzos:['lentejas','alubias'],lentejas:['garbanzos','alubias'],alubias:['garbanzos','lentejas'],tomate:['pimiento','zanahoria'],tomate_trit:['tomate','calabacin'],zanahoria:['calabacin','pimiento'],calabacin:['zanahoria','champi','brocoli'],pimiento:['calabacin','zanahoria'],brocoli:['espinacas','calabacin','guisantes'],espinacas:['brocoli','guisantes'],champi:['calabacin','pimiento'],pepino:['tomate','zanahoria'],queso:['champi','espinacas'],leche:['caldo'],yogur:['manzana','platano'],platano:['manzana'],manzana:['platano'],aceite:['tomate_trit'],guisantes:['espinacas','brocoli'],huevos:['champi','garbanzos'],tortillas:['pan_sg','pan'],pan:['pan_sg','tortillas'],avena:['arroz'],sal:['pimienta'],pimienta:['pimenton','comino'],pimenton:['curry','comino'],curry:['comino','pimenton']};
const animalIds=new Set(['pollo','pavo','atun','merluza','huevos','queso','leche','yogur']);
const glutenRisk=new Set(['pasta','fideos','pan','tortillas','salsa_soja','avena','caldo','curry']);
function getCustom(r){const c=state.customs[r.id]||{};return {remove:Array.isArray(c.remove)?c.remove:[],swap:c.swap||{},extras:c.extras||{}}}
function effectiveIngredients(r){const c=getCustom(r),qty={};r.ingredients.forEach(i=>{if(c.remove.includes(i.id))return;let k=c.swap[i.id]||i.id;if(!state.prices[k])k=i.id;qty[k]=(qty[k]||0)+i.qty});Object.entries(c.extras).forEach(([k,v])=>{if(state.prices[k]&&Number.isFinite(Number(v))&&Number(v)>0)qty[k]=(qty[k]||0)+Number(v)});return Object.entries(qty).filter(([,v])=>v>0).map(([id,q])=>({id,qty:q}))}
function dietWarning(r){const ids=effectiveIngredients(r).map(i=>i.id),alerts=[];
if(r.category==='vegana'&&ids.some(k=>animalIds.has(k)))alerts.push('Esta versión ya no es vegana.');
if(r.category==='sin-gluten'&&ids.some(k=>glutenRisk.has(k)))alerts.push('Comprueba productos certificados sin gluten y contaminación cruzada: hay ingredientes de riesgo.');
if(r.category==='saludable'&&Object.keys(getCustom(r).extras).length)alerts.push('Las calorías originales ya no son válidas tras añadir extras.');
return alerts}
function customCost(r,store='consum',servings=r.servings){return effectiveIngredients(r).reduce((sum,i)=>{const p=state.prices[i.id];return sum+(p?.stores?.[store]?.price||0)*i.qty/p.pack*servings/r.servings},0)}
function cost(r,store='consum',servings=r.servings){return customCost(r,store,servings)}
function storeUrl(p,store){return p?.stores?.[store]?.productUrl|| (store==='consum'?'https://tienda.consum.es/es':'https://tienda.mercadona.es/')}
function storeKind(p,store){return p?.stores?.[store]?.linkType||'tienda'}
function retailerLinks(p,compact=false){return `<span class="retailer-links"><a href="${escapeHtml(storeUrl(p,'consum'))}" target="_blank" rel="noopener noreferrer" title="${storeKind(p,'consum')==='producto'?'Ficha de producto':'Abrir categoría o tienda y buscar el producto'}">Consum ↗${compact?'':' '+(storeKind(p,'consum')==='producto'?'✓':'⌕')}</a><a href="${escapeHtml(storeUrl(p,'mercadona'))}" target="_blank" rel="noopener noreferrer" title="${storeKind(p,'mercadona')==='producto'?'Ficha de producto':'Abrir tienda y buscar el producto'}">Mercadona ↗${compact?'':' '+(storeKind(p,'mercadona')==='producto'?'✓':'⌕')}</a></span>`}
async function saveCustom(r){if(state.user){try{await api('/api/customization',{recipe_id:r.id,customization:getCustom(r)})}catch(err){toast('No se guardó el cambio: '+err.message)}}else try{localStorage.setItem('miga_guest_customs',JSON.stringify(state.customs))}catch{};
renderCards();if(state.plan){renderPlan();renderShopping()}}
function savePantry(){try{localStorage.setItem('miga_pantry_'+(state.user?.id||'guest'),JSON.stringify(state.pantry))}catch{}}
function fmtQty(q,unit){let n=Math.round(q*10)/10;return String(n).replace('.',',')+' '+(unit==='ud'?(n===1?'ud.':'uds.'):unit)}
function statusBadge(s){return s==='oficial'?'<span class="source official" title="Precio consultado en el catálogo oficial">✓ Oficial consultado</span>':s==='referencia'?'<span class="source reference" title="Precio de una web externa">↗ Fuente externa</span>':'<span class="source estimate" title="Precio no verificado">~ Estimación</span>'}
function renderCards(){if(!state.recipes.length)return;const q=state.search.trim().toLocaleLowerCase('es');let rs=state.recipes.filter(r=>(state.cat==='todos'||r.category===state.cat)&&(!state.onlyFav||state.favorites.has(r.id))&&(!q||[r.title,r.description,...r.tags,...r.ingredients.map(x=>state.prices[x.id]?.name||'')].join(' ').toLocaleLowerCase('es').includes(q)));
rs.sort((a,b)=>{if(state.sort==='time')return a.minutes-b.minutes;if(state.sort==='name')return a.title.localeCompare(b.title);if(state.sort==='rating')return (state.ratings[b.id]?.average||0)-(state.ratings[a.id]?.average||0)||cost(a)-cost(b);return cost(a)-cost(b)});
$$('[data-category] span').forEach(n=>{const c=n.parentElement.dataset.category;n.textContent=c==='todos'?state.recipes.length:state.recipes.filter(r=>r.category===c).length});el('resultsCount').textContent=`${rs.length} receta${rs.length===1?'':'s'} para ti`;el('noResults').hidden=rs.length!==0;
el('recipeGrid').innerHTML=rs.map(r=>{const cat=cats[r.category],rating=state.ratings[r.id];return `<article class="recipe-card" data-id="${r.id}"><button class="favorite ${state.favorites.has(r.id)?'saved':''}" data-favorite="${r.id}" aria-label="${state.favorites.has(r.id)?'Quitar de':'Añadir a'} favoritos">${state.favorites.has(r.id)?'♥':'♡'}</button><button class="card-image" data-open="${r.id}" aria-label="Abrir ${escapeHtml(r.title)}"><img loading="eager" src="${escapeHtml(r.photo)}" data-fallback="${escapeHtml(r.fallback)}" alt="Imagen orientativa de ${escapeHtml(r.title)}"><span class="card-tag ${cat.class}">${cat.emoji} ${cat.name}</span></button><div class="card-body"><div class="card-meta"><span>◷ ${r.minutes} min</span><span>${rating?'★ '+rating.average+' ('+rating.count+')':'☆ Sin reseñas'}</span></div><button class="card-title" data-open="${r.id}">${escapeHtml(r.title)}</button><p>${escapeHtml(r.description)}</p><div class="card-bottom"><div><small>COSTE / RACIÓN · CONSUM <span>aprox.</span></small><strong>${euro(cost(r)/r.servings)}</strong></div><button class="card-arrow" data-open="${r.id}" aria-label="Ver receta">↗</button></div></div></article>`}).join('');setupImageFallback(el('recipeGrid'))}
function setupImageFallback(root){
  root.querySelectorAll('img[data-fallback]').forEach(img=>{
    const fallback=()=>{if(!img.src.endsWith('/'+img.dataset.fallback))img.src=img.dataset.fallback};
    img.addEventListener('error',fallback,{once:true});
    if(img.complete&&img.naturalWidth===0)fallback();
  });
}
function recipe(id){return state.recipes.find(r=>r.id===Number(id))}
function openRecipe(id){const r=recipe(id);if(!r)return;state.active=r;state.servings=r.servings;state.step=0;state.checked=new Set();state.selectedStore='consum';stopTimer();renderRecipe();el('recipeLayer').hidden=false;document.body.classList.add('modal-open');el('recipeLayer').querySelector('.modal-x').focus()}
function closeModal(which){el(which==='recipe'?'recipeLayer':'authLayer').hidden=true;if(which==='recipe')stopTimer();document.body.classList.remove('modal-open')}
function ingredientsHtml(){const r=state.active;return effectiveIngredients(r).map(i=>{const p=state.prices[i.id],qty=i.qty*state.servings/r.servings,record=p.stores[state.selectedStore];return `<li><span class="ing-check">✓</span><span class="ing-name">${escapeHtml(p.name)}${retailerLinks(p,true)}</span><strong>${fmtQty(qty,p.unit)}</strong><small title="Precio proporcional estimado">${euro(record.price*qty/p.pack)}</small></li>`}).join('')}
function ingredientBuilder(){const r=state.active,c=getCustom(r);return `<div class="custom-builder"><div class="custom-head"><span class="eyebrow">HAZLA A TU GUSTO</span><h3>Personaliza esta receta ✨</h3><p>Quita lo que no te guste, cambia ingredientes o añade extras. Los importes y la lista semanal se actualizarán.</p></div><div class="custom-rows">${r.ingredients.map(i=>{const name=state.prices[i.id].name;const swaps=(substitutes[i.id]||[]).filter(k=>state.prices[k]?.unit===state.prices[i.id]?.unit);const chosen=c.remove.includes(i.id)?'remove':(c.swap[i.id]||i.id);return `<label class="custom-row"><strong>${escapeHtml(name)} <small>${fmtQty(i.qty*state.servings/r.servings,state.prices[i.id].unit)}</small></strong><select class="custom-select" data-original="${i.id}" aria-label="Sustituir ${escapeHtml(name)}"><option value="${i.id}" ${chosen===i.id?'selected':''}>Mantener</option><option value="remove" ${chosen==='remove'?'selected':''}>✕ Quitar</option>${swaps.map(k=>`<option value="${k}" ${chosen===k?'selected':''}>Cambiar por ${escapeHtml(state.prices[k].name)}</option>`).join('')}</select></label>`}).join('')}</div><div class="extra-controls"><label>¿Quieres añadir un extra?<select id="extraIngredient"><option value="">Elige un ingrediente…</option>${Object.keys(state.prices).sort((a,b)=>state.prices[a].name.localeCompare(state.prices[b].name,'es')).map(k=>`<option value="${k}">${escapeHtml(state.prices[k].name)} (${state.prices[k].unit})</option>`).join('')}</select></label><label>Cantidad<input id="extraQty" type="number" min="1" max="5000" step="1" value="50" aria-label="Cantidad del extra"></label><button class="button subdued small" type="button" id="addExtra">+ Añadir</button></div><div id="extraList" class="extras-list">${Object.entries(c.extras).map(([k,v])=>`<div class="extra-chip"><span>+ ${escapeHtml(state.prices[k]?.name||k)} · ${fmtQty(v,state.prices[k]?.unit||'g')}</span><button type="button" data-remove-extra="${k}" aria-label="Quitar este extra">×</button></div>`).join('')||'<small>No has añadido extras todavía.</small>'}</div><div id="dietWarnings" class="custom-warning">${dietWarning(r).map(m=>`⚠ ${escapeHtml(m)}`).join('<br>')||'✓ Personalización lista. Comprueba siempre las etiquetas de alérgenos.'}</div><button type="button" class="reset-custom" id="resetCustom">↺ Volver a la receta original</button></div>`}
function refreshIngredients(){const r=state.active;if(!r)return;el('ingredientList').innerHTML=ingredientsHtml();el('recipeTotal').textContent=euro(cost(r,state.selectedStore,state.servings));el('customBuilder').innerHTML=ingredientBuilder();bindIngredientBuilder()}
function bindIngredientBuilder(){document.querySelectorAll('#customBuilder [data-original]').forEach(sel=>{sel.onchange=async()=>{const r=state.active,c=getCustom(r),id=sel.dataset.original,v=sel.value;c.remove=c.remove.filter(x=>x!==id);delete c.swap[id];if(v==='remove')c.remove.push(id);else if(v!==id)c.swap[id]=v;state.customs[r.id]=c;refreshIngredients();await saveCustom(r)}});
document.querySelectorAll('#customBuilder [data-remove-extra]').forEach(b=>{b.onclick=async()=>{const r=state.active,c=getCustom(r);delete c.extras[b.dataset.removeExtra];state.customs[r.id]=c;refreshIngredients();await saveCustom(r)}});
el('addExtra').onclick=async()=>{const r=state.active,c=getCustom(r),key=el('extraIngredient').value,qty=Number(el('extraQty').value);if(!state.prices[key]||!Number.isFinite(qty)||qty<1||qty>5000)return toast('Elige un extra y una cantidad válida.');c.extras[key]=Math.min(5000,(Number(c.extras[key])||0)+qty);state.customs[r.id]=c;refreshIngredients();await saveCustom(r);toast('Extra añadido a la receta y a la lista de compra.');};
el('resetCustom').onclick=async()=>{const r=state.active;delete state.customs[r.id];refreshIngredients();await saveCustom(r)}}
function renderRecipe(){const r=state.active;const cat=cats[r.category];const reviewable=state.completed.has(r.id)&&!!state.user;const photo=r.photo;el('recipeModalContent').innerHTML=`<div class="recipe-hero"><div class="recipe-hero-image"><img src="${escapeHtml(photo)}" data-fallback="${escapeHtml(r.fallback)}" alt="Imagen asociada a ${escapeHtml(r.title)}" id="detailImage"><button class="zoom-photo" id="zoomImage">⛶ Ampliar foto</button></div><div class="recipe-heading"><span class="recipe-badge ${cat.class}">${cat.emoji} ${cat.name}</span><h2>${escapeHtml(r.title)}</h2><p>${escapeHtml(r.description)}</p><div class="recipe-facts"><span>◷ ${r.minutes} minutos</span><span>♙ ${state.servings} raciones</span><span>⚡ ${r.kcal} kcal aprox./ración*</span></div><p class="photo-credit">📷 Imagen ilustrativa generada para MIGA. El aspecto final puede variar.</p><div class="recipe-heading-actions"><button class="button subdued" id="detailFav">${state.favorites.has(r.id)?'♥ Guardada':'♡ Guardar receta'}</button><button class="button share-recipe" id="detailShare" type="button">↗ Compartir receta</button><a class="button video-button" href="https://www.youtube.com/results?search_query=${encodeURIComponent(r.videoSearch)}" target="_blank" rel="noopener noreferrer">▶ Ver vídeos relacionados ↗</a></div></div></div><div class="recipe-content"><div class="recipe-main"><div class="recipe-section-heading"><span class="eyebrow">COCINA A TU RITMO</span><h3>Paso a paso</h3></div><div class="step-card" id="stepCard"></div><div class="step-controls"><button class="button subdued" id="prevStep">← Anterior</button><span id="stepProgress">Paso 1 de ${r.steps.length}</span><button class="button primary" id="nextStep">Siguiente →</button></div><div class="video-section"><h4>▶ Videoreceta relacionada</h4>${r.videoId?`<div class="embed"><iframe src="https://www.youtube-nocookie.com/embed/${r.videoId}" title="${escapeHtml(r.videoTitle)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div><p class="small-note">${escapeHtml(r.videoNote)}</p>`:`<p class="small-note">Puedes ver otras preparaciones similares en YouTube. Los ingredientes y tiempos pueden cambiar.</p>`}<a class="video-out" href="https://www.youtube.com/results?search_query=${encodeURIComponent(r.videoSearch)}" target="_blank" rel="noopener noreferrer">Ver más vídeos de esta receta ↗</a></div><div class="timer-area"><div><h4>⏱ Temporizador de cocina</h4><p>Ponlo en marcha cuando lo necesites.</p></div><div class="timer-actions"><button data-timer="5">5 min</button><button data-timer="10">10 min</button><button data-timer="15">15 min</button><button data-timer="20">20 min</button></div><div class="timer-time" id="timerTime">00:00</div><button class="button subdued small" id="stopTimer">Parar</button></div><div class="review-section"><div class="recipe-section-heading"><span class="eyebrow">TU OPINIÓN AYUDA</span><h3>Reseñas de la comunidad</h3></div><div id="reviewsList"><p>Cargando reseñas…</p></div><div id="writeReview"></div></div></div><aside class="ingredients-panel"><div class="recipe-section-heading"><span class="eyebrow">TODO LO NECESARIO</span><h3>Ingredientes</h3></div><div class="serving-stepper"><span>Raciones</span><div><button id="lessServing" aria-label="Menos raciones">−</button><strong id="servingNumber">${state.servings}</strong><button id="moreServing" aria-label="Más raciones">+</button></div></div><label class="store-choice">Precios orientativos de <select id="recipeStore"><option value="consum">Consum</option><option value="mercadona">Mercadona</option></select></label><ul class="ingredient-list" id="ingredientList">${ingredientsHtml()}</ul><div id="customBuilder">${ingredientBuilder()}</div><div class="ingredient-total"><span>Coste de ingredientes usados <small>Estimación según tu personalización, no envases</small></span><strong id="recipeTotal">${euro(cost(r,state.selectedStore,state.servings))}</strong></div><p class="small-note">Quita, sustituye o añade alimentos a tu gusto. Los precios no son en tiempo real.</p><div class="allergen-note">${r.category==='sin-gluten'?'🌾 <strong>Sin gluten:</strong> elige productos certificados cuando corresponda y evita contaminación cruzada.':'ⓘ Comprueba siempre etiquetas y alérgenos. Las calorías son aproximaciones, no valores nutricionales certificados.'}</div></aside></div><div class="modal-bottom">* Calorías aproximadas en la receta base. Cambian según marcas y preparación. Imagen ilustrativa; los vídeos abren búsquedas de recetas similares, no tutoriales validados exactamente para este plato.</div>`;
setupImageFallback(el('recipeModalContent'));updateStep();renderReviews();bindIngredientBuilder();
el('detailFav').onclick=()=>toggleFav(r.id);el('detailShare').onclick=()=>shareMigaRecipe(r);el('recipeStore').onchange=e=>{state.selectedStore=e.target.value;refreshIngredients()};el('lessServing').onclick=()=>changeServing(-1);el('moreServing').onclick=()=>changeServing(1);el('prevStep').onclick=()=>{state.step=Math.max(0,state.step-1);updateStep()};el('nextStep').onclick=advanceStep;el('stopTimer').onclick=stopTimer;el('timerTime').textContent='00:00';$$('[data-timer]').forEach(b=>b.onclick=()=>startTimer(Number(b.dataset.timer)));
el('zoomImage').onclick=()=>{el('detailImage').classList.toggle('zoomed');el('zoomImage').textContent=el('detailImage').classList.contains('zoomed')?'− Reducir foto':'⛶ Ampliar foto'};}
function changeServing(delta){state.servings=Math.max(1,Math.min(10,state.servings+delta));el('servingNumber').textContent=state.servings;refreshIngredients();}
function updateStep(){const r=state.active,s=state.step,detail=r.stepDetails?.[s]||{};
const modified=effectiveIngredients(r).map(x=>x.id+':'+x.qty).join('|')!==r.ingredients.map(x=>x.id+':'+x.qty).join('|');
el('stepCard').innerHTML=`<div class="step-indicator"><span>PASO ${String(s+1).padStart(2,'0')}</span><span>DE ${String(r.steps.length).padStart(2,'0')}</span></div><div class="step-bars">${r.steps.map((_,i)=>`<i class="${i<=s?'lit':''}"></i>`).join('')}</div><div class="step-prep"><span class="step-prep-emoji">${['🥕','🍳','🥣','🔥','🍽'][s%5]}</span><div><small>QUÉ NECESITAS AHORA</small><strong>${escapeHtml(detail.needs||'Ten preparados los ingredientes y utensilios del paso.')}</strong></div></div><div class="step-instruction"><small>QUÉ TIENES QUE HACER</small><p>${escapeHtml(r.steps[s])}</p></div>${detail.tip?`<div class="step-tip"><b>💡 En qué fijarte</b><p>${escapeHtml(detail.tip)}</p></div>`:''}${modified?'<div class="step-modified">Has personalizado ingredientes: adapta estos pasos y comprueba los nuevos tiempos de cocción.</div>':''}<button class="voice-btn" id="readStep">◖)) Escuchar este paso</button>`;
el('readStep').onclick=()=>{if(!('speechSynthesis' in window))return toast('Tu navegador no admite lectura de voz.');speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(`${detail.needs?'Necesitas '+detail.needs+'. ':''}${r.steps[s]} ${detail.tip||''}`);utter.lang='es-ES';utter.rate=.91;speechSynthesis.speak(utter)};
el('stepProgress').textContent=`Paso ${s+1} de ${r.steps.length}`;el('prevStep').disabled=s===0;el('nextStep').textContent=s===r.steps.length-1?'✓ Terminé la receta':'Siguiente →'}
async function advanceStep(){if(state.step<state.active.steps.length-1){state.step++;updateStep();return}if(!state.user){toast('¡Enhorabuena! Crea una cuenta para guardar que has cocinado la receta y poder reseñarla.');openAuth('register');return}try{await api('/api/completed',{recipe_id:state.active.id});state.completed.add(state.active.id);toast('¡Receta completada! Ya puedes dejar tu reseña.');renderReviews();el('nextStep').textContent='✓ Cocinada';}catch(e){toast(e.message)}}
function startTimer(m){stopTimer();state.remaining=m*60;state.timerEnd=Date.now()+m*60*1000;const draw=()=>{state.remaining=Math.max(0,Math.ceil((state.timerEnd-Date.now())/1000));if(el('timerTime'))el('timerTime').textContent=String(Math.floor(state.remaining/60)).padStart(2,'0')+':'+String(state.remaining%60).padStart(2,'0');if(state.remaining<=0){stopTimer(false);toast('⏰ ¡Tiempo terminado!')}};draw();state.timer=setInterval(draw,400)}
function stopTimer(reset=true){if(state.timer){clearInterval(state.timer);state.timer=null}if(reset&&el('timerTime'))el('timerTime').textContent='00:00'}
async function renderReviews(){const rid=state.active?.id;if(!rid)return;try{const dat=await api('/api/reviews?recipe='+rid);if(state.active?.id!==rid)return;el('reviewsList').innerHTML=dat.reviews.length?`<div class="review-head">★ ${dat.average}/5 · ${dat.count} reseña${dat.count!==1?'s':''}</div>`+dat.reviews.map(rev=>`<article class="review"><div><b>${escapeHtml(rev.name)}</b><span>${'★'.repeat(rev.rating)}${'☆'.repeat(5-rev.rating)}</span></div><p>${escapeHtml(rev.comment)}</p><small>${new Date(rev.created_at).toLocaleDateString('es-ES')}</small></article>`).join(''):'<p class="muted">Aún no hay reseñas. ¿Serás la primera persona en cocinarla?</p>';
let html;if(!state.user)html='<p class="review-prompt">Inicia sesión y termina la receta para compartir tu experiencia.</p><button class="button subdued" id="reviewLogin">Entrar / Registrarme</button>';
else if(!state.completed.has(rid))html='<p class="review-prompt">Para valorar esta receta, primero sigue los pasos y pulsa «Terminé la receta».</p>';
else html=`<form id="reviewForm"><h4>¿Cómo te salió?</h4><label>Puntuación<select name="rating"><option value="5">★★★★★ (5)</option><option value="4">★★★★☆ (4)</option><option value="3">★★★☆☆ (3)</option><option value="2">★★☆☆☆ (2)</option><option value="1">★☆☆☆☆ (1)</option></select></label><label>Tu experiencia y cómo mejorarla<textarea name="comment" minlength="15" maxlength="600" required rows="4" placeholder="Cuéntanos cómo te quedó, qué cambiarías o qué truco recomendarías…"></textarea></label><button class="button primary" type="submit">Publicar reseña →</button></form>`;
el('writeReview').innerHTML=html;if(el('reviewLogin'))el('reviewLogin').onclick=()=>openAuth('login');if(el('reviewForm'))el('reviewForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target);try{await api('/api/review',{recipe_id:rid,rating:Number(form.get('rating')),comment:String(form.get('comment'))});toast('¡Gracias por compartir tu experiencia!');const ratings=await api('/api/ratings');state.ratings=Object.fromEntries(ratings.ratings.map(r=>[r.recipe_id,r]));renderCards();renderReviews()}catch(err){toast(err.message)}}}catch(e){el('reviewsList').textContent=e.message}}
async function toggleFav(id){if(!state.user){toast('Inicia sesión para guardar tus favoritas.');openAuth('login');return}const on=!state.favorites.has(id);try{await api('/api/favorite',{recipe_id:id,active:on});if(on)state.favorites.add(id);else state.favorites.delete(id);toast(on?'Receta guardada en favoritos ♡':'Receta quitada de favoritos');renderCards();if(state.active?.id===id)el('detailFav').textContent=on?'♥ Guardada':'♡ Guardar receta';}catch(e){toast(e.message)}}
function openAuth(mode='login'){state.authMode=mode;renderAuth();el('authLayer').hidden=false;document.body.classList.add('modal-open')}
function renderAuth(){const u=state.user;if(u){el('authContent').innerHTML=`<div class="auth-decor">✳</div><span class="eyebrow">TU RINCÓN EN MIGA</span><h2>¡Hola, ${escapeHtml(u.name)}!</h2><p>Tu cuenta está activa. Puedes guardar tus favoritas, guardar el menú semanal y valorar las recetas que has cocinado.</p><div class="account-info"><span>Correo</span><b>${escapeHtml(u.email)}</b><span>Favoritas</span><b>${state.favorites.size} recetas</b><span>Recetas cocinadas</span><b>${state.completed.size}</b></div><a class="button subdued wide" href="/api/account/export" download="mis-datos-miga.json" style="text-align:center">Descargar mis datos</a><button class="button subdued wide" id="deleteAccount">Eliminar mi cuenta</button><button class="button subdued wide" id="logout">Cerrar sesión →</button>`;el('logout').onclick=logout;el('deleteAccount').onclick=async()=>{if(!confirm('¿Quieres borrar tu cuenta, reseñas y datos guardados de forma permanente?'))return;const password=prompt('Para confirmar, introduce tu contraseña:');if(!password)return;try{await api('/api/account/delete',{password});state.user=null;state.csrf='';const d=await api('/api/bootstrap');hydrate(d);closeModal('auth');navigate('inicio');toast('Cuenta eliminada.')}catch(e){toast(e.message)}};return}
const register=state.authMode==='register'&&state.registrationOpen;el('authContent').innerHTML=`<div class="auth-decor">✳</div><span class="eyebrow">BIENVENIDO A TU COCINA</span><h2>${register?'Empieza a cocinar.':'Qué bien verte.'}</h2><p>${register?'Guarda recetas, publica reseñas y planifica tu semana sin perder nada.':'Entra para recuperar tus favoritas y menús.'}</p><div class="auth-tabs"><button class="${!register?'active':''}" data-auth-mode="login">Iniciar sesión</button><button class="${register?'active':''}" data-auth-mode="register" ${state.registrationOpen?'':'disabled title="Registro público temporalmente cerrado"'}>Crear cuenta</button></div><form id="authForm">${register?'<label>Tu nombre<input name="name" required minlength="2" maxlength="60" autocomplete="name" placeholder="Ej. Alex García"></label>':''}<label>Correo electrónico<input name="email" type="email" required autocomplete="email" placeholder="tunombre@correo.com"></label><label>Contraseña<input name="password" type="password" required minlength="${register?12:8}" maxlength="256" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'12 caracteres como mínimo':'Tu contraseña'}"></label>${register?'<label class="contact-consent"><input type="checkbox" name="consent" value="yes" required><span>He leído la <a href="/privacidad" target="_blank" rel="noopener">política de privacidad</a> y acepto el tratamiento de mis datos para crear mi cuenta.</span></label>':''}<label class="remember-me"><input type="checkbox" name="remember" value="yes"><span><strong>Recordarme</strong><small>Mantener la sesión durante 30 días en este dispositivo. Si no lo marcas, se cerrará al cerrar el navegador o tras 12 horas.</small></span></label><button class="button primary wide" type="submit">${register?'Crear mi cuenta →':'Iniciar sesión →'}</button>${!register?'<p><a href="/recuperar">¿Has olvidado tu contraseña?</a></p><p><a href="/verificar">¿No has recibido el correo de verificación?</a></p>':''}<p class="privacy-copy">Tus datos se guardan para gestionar tu cuenta. Consulta la <a href="/privacidad" target="_blank" rel="noopener">política de privacidad</a> y el <a href="/aviso-legal" target="_blank" rel="noopener">aviso legal</a>.</p></form>`;$$('[data-auth-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.authMode==='register'&&!state.registrationOpen)return toast('El registro público estará disponible tras completar la información legal.');state.authMode=b.dataset.authMode;renderAuth()});el('authForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const body=Object.fromEntries(f.entries());body.remember=f.has('remember');body.consent=f.has('consent');try{const a=await api(register?'/api/register':'/api/login',body);if(a.verificationRequired){closeModal('auth');toast('Comprueba tu correo para activar MIGA. Revisa también Spam.');alert(a.message);return;}hydrate(a);if(a.plan){state.plan=normalizePlan(a.plan);renderPlan();renderShopping();}renderCards();closeModal('auth');toast(register?'¡Cuenta creada! Bienvenido a MIGA.':'¡Bienvenido otra vez!')}catch(err){toast(err.message)}}}
async function logout(){try{await api('/api/logout',{});state.user=null;state.favorites=new Set();state.completed=new Set();state.csrf='';const data=await api('/api/bootstrap');hydrate(data);closeModal('auth');renderCards();navigate('inicio');toast('Sesión cerrada correctamente.')}catch(e){toast(e.message)}}
const weekNames=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
function normalizePlan(p){if(!p||!Array.isArray(p.ids))return null;const ids=p.ids.filter(id=>recipe(id));if(ids.length===7){const dinners=ids.map((id,i)=>{const choices=state.recipes.filter(r=>r.id!==id).sort((a,b)=>cost(a,p.store||'consum',p.servings||2)-cost(b,p.store||'consum',p.servings||2));return choices[(i+3)%Math.max(1,Math.min(choices.length,10))]?.id||id});return {...p,ids:ids.flatMap((id,i)=>[id,dinners[i]])}}return p.ids.length===14&&p.ids.every(id=>id===null||!!recipe(id))?{...p,ids:[...p.ids]}:null}
function calculatePlan(ids,serv,store){return ids.reduce((sum,id)=>sum+(recipe(id)?cost(recipe(id),store,serv):0),0)}
function proteinGroup(r){const ids=effectiveIngredients(r).map(i=>i.id);if(ids.some(id=>['pollo','pavo','lomo_cerdo','picada_mixta'].includes(id)))return 'carne';if(ids.some(id=>['atun','merluza'].includes(id)))return 'pescado';if(ids.includes('huevos'))return 'huevos';if(ids.some(id=>['lentejas','alubias','garbanzos'].includes(id)))return 'legumbres';return 'verduras'}
function makePlan(){const budget=Number(el('budget').value),serv=Number(el('people').value),cat=el('diet').value,store=el('plannerStore').value;if(!Number.isFinite(budget)||budget<5||budget>1000)return toast('Introduce un presupuesto entre 5 y 1000 €.');const eligible=state.recipes.filter(r=>cat==='todos'||r.category===cat);if(!eligible.length)return;
// Mix affordable meals and dinners; different protein groups, meat/poultry options for mixed diets.
const ids=[],used=new Map(),groupUsed=new Map();let prev=-1;
for(let i=0;i<14;i++){
 const choices=eligible.map(r=>{const group=proteinGroup(r);const repeats=used.get(r.id)||0;const score=cost(r,store,serv)+repeats*1.1+(r.id===prev?4:0)+(groupUsed.get(group)||0)*.15+(i%2===1&&r.minutes>35?.45:0);return {r,score,group}}).sort((a,b)=>a.score-b.score);
 let item=choices[0];if(cat==='todos'&&i%3===0){const meats=choices.filter(x=>x.group==='carne');if(meats.length)item=meats[0]}
 ids.push(item.r.id);used.set(item.r.id,(used.get(item.r.id)||0)+1);groupUsed.set(item.group,(groupUsed.get(item.group)||0)+1);prev=item.r.id;
}
state.plan={ids,servings:serv,budget,category:cat,store};persistPlan();renderPlan();renderShopping();toast('¡Tus 7 comidas y 7 cenas están preparadas! Puedes cambiarlas libremente.')}
let planSaveTimer=null;
function persistPlan(){try{localStorage.setItem('miga_plan',JSON.stringify(state.plan))}catch{};if(state.user&&state.plan){clearTimeout(planSaveTimer);planSaveTimer=setTimeout(()=>api('/api/plan',state.plan).catch(e=>toast('No se ha podido sincronizar el menú: '+e.message)),450)}}
function eligibleMeals(p){return state.recipes.filter(r=>p.category==='todos'||r.category===p.category).sort((a,b)=>cost(a,p.store,p.servings)-cost(b,p.store,p.servings))}
function changeMeal(i,direction){const p=state.plan;if(!p)return;const eligible=eligibleMeals(p);if(!eligible.length)return;const ix=eligible.findIndex(r=>r.id===p.ids[i]);p.ids[i]=eligible[ix===-1?0:(ix+direction+eligible.length)%eligible.length].id;persistPlan();renderPlan();renderShopping()}
function chooseMeal(i,id){if(!state.plan)return;if(id!==null&&!recipe(id))return;state.plan.ids[i]=id;persistPlan();renderPlan();renderShopping();toast(id===null?'Casilla vacía. Puedes poner otro plato.':'Plato actualizado ✓')}
function removeMeal(i){if(!state.plan||state.plan.ids[i]===null)return;state.plan.ids[i]=null;persistPlan();renderPlan();renderShopping();toast('Plato quitado: no se contará en la compra ni en el precio.')}
function newEmptyPlan(){return {ids:Array(14).fill(null),servings:Number(el('people')?.value||2),budget:Number(el('budget')?.value||65),category:'todos',store:el('plannerStore')?.value||'consum'}}
function renderPlan(){if(!state.plan)return;el('planPlaceholder').hidden=true;el('planOutput').hidden=false;const p=state.plan;const store=p.store||'consum';const total=calculatePlan(p.ids,p.servings,store);const goal=Number(p.budget||el('budget').value);const filled=p.ids.filter(id=>id!==null).length;
el('planCost').textContent=euro(total);el('planPer').textContent=`${filled} de 14 platos elegidos · ${p.servings} persona${p.servings!==1?'s':''} · ${store==='consum'?'Consum':'Mercadona'}`;
el('budgetMeter').style.width=Math.min(100,total/goal*100)+'%';el('budgetMeter').classList.toggle('over',total>goal);el('budgetStatus').innerHTML=total<=goal?`<strong>✓ ${filled===14?'Dentro del presupuesto':'Coste parcial del menú'}</strong><span>${filled===14?'Te quedan':'Disponible antes de completar'} ${euro(goal-total)}*</span>`:`<strong class="over-label">+ ${euro(total-goal)} sobre el objetivo</strong><span>Prueba a elegir platos más económicos.</span>`;
el('planDays').innerHTML=weekNames.map((name,day)=>`<article class="week-day"><div class="week-day-head"><strong>${name}</strong><small>DÍA ${String(day+1).padStart(2,'0')}</small></div><div class="meal-grid">${[0,1].map(slot=>{const i=day*2+slot,id=p.ids[i],r=id===null?null:recipe(id),cat=r?cats[r.category]:null;return `<section class="meal-card ${r?'':'meal-empty'}" data-slot="${i}" aria-label="${slot?'Cena':'Comida'} del ${name}"><div class="meal-label">${slot?'🌙 CENA':'☀️ COMIDA'} <span>${r?cat.emoji+' '+cat.name:'Sin asignar'}</span></div>${r?`<div class="meal-summary"><img src="${escapeHtml(r.photo)}" data-fallback="${escapeHtml(r.fallback)}" alt="${escapeHtml(r.title)}"><div><button class="meal-open" data-open="${id}">${escapeHtml(r.title)} ↗</button><small>◷ ${r.minutes} min · ${euro(cost(r,store,p.servings))}</small></div></div>`:`<div class="meal-open-space"><span>＋</span><div><strong>Plato eliminado</strong><small>Elige uno o descubre ideas con tus ingredientes.</small></div></div>`}<div class="meal-picker"><button type="button" data-shift="-1" data-slot-index="${i}" aria-label="Plato anterior">‹</button><select data-choice="${i}" aria-label="Elegir ${slot?'cena':'comida'} del ${name}"><option value="" ${!r?'selected':''}>${r?'Cambiar plato…':'Seleccionar receta…'}</option>${state.recipes.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${escapeHtml(x.title)}</option>`).join('')}</select><button type="button" data-shift="1" data-slot-index="${i}" aria-label="Plato siguiente">›</button></div><div class="meal-actions">${r?`<button type="button" class="remove-meal" data-remove-meal="${i}">✕ Quitar plato</button>`:`<button type="button" class="find-meal" data-page="crear">✦ Crear un plato →</button>`}</div></section>`}).join('')}</div></article>`).join('');setupImageFallback(el('planDays'));
$$('[data-choice]').forEach(select=>select.onchange=()=>{const val=select.value;chooseMeal(Number(select.dataset.choice),val?Number(val):null)});
$$('[data-shift]').forEach(b=>b.onclick=()=>changeMeal(Number(b.dataset.slotIndex),Number(b.dataset.shift)));
$$('[data-remove-meal]').forEach(b=>b.onclick=()=>removeMeal(Number(b.dataset.removeMeal)));
$$('.meal-card').forEach(card=>{let x=null,y=null;card.addEventListener('touchstart',e=>{if(e.target.closest('button,select,a'))return;x=e.touches[0].clientX;y=e.touches[0].clientY},{passive:true});card.addEventListener('touchend',e=>{if(x===null)return;const dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;x=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.5)changeMeal(Number(card.dataset.slot),dx<0?1:-1)},{passive:true})})}
function shoppingItems(){if(!state.plan)return [];const qty={};state.plan.ids.forEach(id=>{const r=id===null?null:recipe(id);if(!r)return;effectiveIngredients(r).forEach(i=>{qty[i.id]=(qty[i.id]||0)+i.qty*state.plan.servings/r.servings})});return Object.entries(qty).filter(([key])=>state.prices[key]).map(([key,amount])=>({key,...state.prices[key],qty:amount})).sort((a,b)=>a.name.localeCompare(b.name,'es'))}

function renderPlateBuilder(){
 const shell=el('plateIngredients');if(!shell)return;
 const term=(el('plateSearch')?.value||'').trim().toLocaleLowerCase('es');
 const entries=Object.entries(state.prices).sort((a,b)=>a[1].name.localeCompare(b[1].name,'es'));
 const filtered=entries.filter(([id,p])=>!term||p.name.toLocaleLowerCase('es').includes(term)).slice(0,90);
 el('plateAmount').textContent=`${state.plateIngredients.size} elegidos de ${entries.length}`;
 shell.innerHTML=filtered.map(([id,p])=>`<button type="button" class="ingredient-tile ${state.plateIngredients.has(id)?'selected':''}" data-ingredient="${escapeHtml(id)}" aria-pressed="${state.plateIngredients.has(id)}"><span class="ingredient-symbol">${plateIcon(id)}</span><span>${escapeHtml(p.name)}</span><small>${state.plateIngredients.has(id)?'✓ Elegido':'＋ Añadir'}</small></button>`).join('')||'<p>No hay ingredientes que coincidan. Prueba con otra búsqueda.</p>';
 $$('#plateIngredients [data-ingredient]').forEach(b=>b.onclick=()=>{const id=b.dataset.ingredient;state.plateFromFridge=false;if(state.plateIngredients.has(id))state.plateIngredients.delete(id);else state.plateIngredients.add(id);renderPlateBuilder()});
 const selected=[...state.plateIngredients];el('plateSelected').innerHTML=selected.length?selected.map(id=>`<button type="button" class="selected-ingredient" data-delete-ingredient="${escapeHtml(id)}">${escapeHtml(state.prices[id].name)} <b>×</b></button>`).join(''):'<span class="muted">Selecciona varios ingredientes: pollo, arroz, tomate, verduras…</span>';
 $$('#plateSelected [data-delete-ingredient]').forEach(b=>b.onclick=()=>{state.plateFromFridge=false;state.plateIngredients.delete(b.dataset.deleteIngredient);renderPlateBuilder()});
 renderPlateRecommendations();
}
function plateIcon(id){if(['pollo','pavo','lomo_cerdo','picada_mixta'].includes(id))return '🥩';if(['atun','merluza'].includes(id))return '🐟';if(['arroz','pasta','pasta_sg','fideos'].includes(id))return '🍚';if(['huevos','leche','queso','yogur'].includes(id))return '🥚';if(['lentejas','garbanzos','alubias'].includes(id))return '🫘';if(['patata','cebolla','ajo','zanahoria','calabacin','pimiento','tomate','lechuga','pepino','brocoli','champi','espinacas'].includes(id))return '🥬';return '🍽️'}
function plateRecommendation(r,picks){const list=effectiveIngredients(r),ids=list.map(i=>i.id),matches=ids.filter(id=>picks.has(id));const missing=list.filter(i=>!picks.has(i.id));const extraCost=missing.reduce((sum,i)=>{const p=state.prices[i.id];return sum+(p?.stores?.consum?.price||0)*i.qty/p.pack},0);return {r,matches,missing,extraCost,coverage:matches.length/Math.max(1,ids.length)}}
function renderPlateRecommendations(){const results=el('plateResults');if(!results)return;const picks=state.plateIngredients;if(!picks.size){results.innerHTML='<div class="plate-initial"><span>🍳</span><h3>¿Qué tienes en la cocina?</h3><p>Elige los ingredientes que quieras aprovechar y MIGA encontrará recetas de verdad, con preparación y precio.</p></div>';el('plateResultCount').textContent='Añade ingredientes para ver sugerencias';return}
 const category=state.plateType;const onlyComplete=state.plateStrict;
 const candidates=state.recipes.filter(r=>category==='todos'||r.category===category).map(r=>plateRecommendation(r,picks)).filter(x=>x.matches.length>=1&&(!onlyComplete||x.missing.length===0));
 candidates.sort((a,b)=>{const score=x=>x.matches.length*6-x.missing.length*3+x.coverage*4-x.extraCost*.5;return score(b)-score(a)||a.missing.length-b.missing.length||cost(a.r)-cost(b.r)});
 const take=candidates.slice(0,9);el('plateResultCount').textContent=`${candidates.length} recetas que encajan con tu selección`;
 results.innerHTML=take.length?take.map((m,idx)=>`<article class="plate-result ${idx===0?'plate-best':''}"><div class="plate-result-image"><img loading="eager" src="${escapeHtml(m.r.photo)}" data-fallback="${escapeHtml(m.r.fallback)}" alt="${escapeHtml(m.r.title)}"></div><div class="plate-result-body"><div class="plate-result-top"><span class="card-tag ${cats[m.r.category].class}">${cats[m.r.category].emoji} ${cats[m.r.category].name}</span>${idx===0?'<b class="plate-recommended">✦ Recomendación MIGA</b>':''}</div><h3>${escapeHtml(m.r.title)}</h3><p class="plate-rank">✓ ${m.matches.length} de ${m.matches.length+m.missing.length} ingredientes de esta receta ya seleccionados</p><div class="plate-match"><b>Tienes:</b> ${m.matches.map(id=>escapeHtml(state.prices[id]?.name||id)).join(', ')}.</div>${m.missing.length?`<div class="plate-missing"><b>Te faltan:</b> ${m.missing.map(i=>escapeHtml(state.prices[i.id]?.name||i.id)+' ('+fmtQty(i.qty,state.prices[i.id]?.unit||'g')+')').join(', ')}.</div>`:'<div class="plate-all">✓ Puedes prepararla con los ingredientes elegidos (si tienes cantidad suficiente).</div>'}<div class="plate-estimates"><span>◷ ${m.r.minutes} min</span><span>Desde ${euro(cost(m.r,'consum')/m.r.servings)}/ración*</span><span>Faltante ${euro(m.extraCost)}*</span></div><div class="plate-actions"><button class="button primary small" data-open="${m.r.id}">Ver preparación →</button><div class="plate-add"><select aria-label="Hueco del menú para ${escapeHtml(m.r.title)}" data-plate-slot="${m.r.id}">${weekNames.flatMap((day,d)=>[0,1].map(sl=>`<option value="${d*2+sl}" ${d*2+sl===(state.plan?.ids.findIndex(x=>x===null)??-1)?'selected':''}>${day} · ${sl?'Cena':'Comida'}</option>`)).join('')}</select><button class="button subdued small" data-plate-add="${m.r.id}">＋ Al menú</button></div></div></div></article>`).join(''):'<div class="plate-initial"><span>🥗</span><h3>No hay coincidencias completas</h3><p>Prueba a añadir otro ingrediente, cambiar la categoría o desactivar «Solo con lo elegido».</p></div>';
 setupImageFallback(results);
 $$('[data-plate-add]').forEach(btn=>btn.onclick=()=>{const id=Number(btn.dataset.plateAdd);const index=Number($(`[data-plate-slot="${id}"]`)?.value||0);if(!state.plan)state.plan=newEmptyPlan();state.plan.ids[index]=id;persistPlan();renderPlan();renderShopping();renderPlateRecommendations();toast(`${recipe(id).title}: añadido a ${weekNames[Math.floor(index/2)]}, ${index%2?'cena':'comida'}.`)});
}
function pantryHave(p){if(Object.prototype.hasOwnProperty.call(state.pantry,p.key)){const v=state.pantry[p.key];return v==='all'?p.qty:Math.max(0,Number(v)||0)*p.pack}const f=state.fridge[p.key];return f && Number(f.qty)>0 && (!f.expiry || Date.parse(f.expiry+'T23:59:59')>=Date.now())?Math.max(0,Number(f.qty)||0):0}
function shopPacks(p){return Math.max(0,Math.ceil((p.qty-pantryHave(p)-1e-6)/p.pack))}
function renderShopping(){if(!state.plan){el('shoppingEmpty').hidden=false;el('shoppingContent').hidden=true;return}el('shoppingEmpty').hidden=true;el('shoppingContent').hidden=false;const its=shoppingItems(),store=state.shoppingStore;
const spend=s=>its.reduce((sum,p)=>sum+shopPacks(p)*p.stores[s].price,0);
el('usedConsum').textContent=euro(its.reduce((sum,p)=>sum+p.qty/p.pack*p.stores.consum.price,0));el('packConsum').textContent=euro(spend('consum'));el('packMercadona').textContent=euro(spend('mercadona'));
el('shoppingStore').value=store;
el('shoppingList').innerHTML=its.map((p,i)=>{const packs=shopPacks(p),have=state.pantry[p.key]||'auto';return `<div class="shop-item shop-detail" data-shop-key="${p.key}"><div class="shop-product"><b>${escapeHtml(p.name)}</b><small>Para las recetas: ${fmtQty(p.qty,p.unit)} · envase orientativo de ${fmtQty(p.pack,p.unit)}</small><label class="have-select">¿Qué tienes en casa? <select data-pantry="${p.key}" aria-label="Cantidad disponible de ${escapeHtml(p.name)}"><option value="auto" ${have==='auto'?'selected':''}>Usar mi nevera (${fmtQty(fridgeUsable(state.fridge[p.key])?(state.fridge[p.key]?.qty||0):0,p.unit)})</option><option value="0" ${have==='0'?'selected':''}>No tengo</option><option value="0.5" ${have==='0.5'?'selected':''}>Medio envase</option><option value="1" ${have==='1'?'selected':''}>1 envase</option><option value="2" ${have==='2'?'selected':''}>2 envases</option><option value="all" ${have==='all'?'selected':''}>Tengo suficiente</option></select></label>${retailerLinks(p)}</div><span class="shop-item-prices"><strong class="${packs===0?'zero-price':''}">${packs?euro(packs*p.stores[store].price):'0,00 €'}</strong><small>${packs===0?'✓ Ya lo tienes':`Falta comprar ${packs} envase${packs!==1?'s':''}`}</small><small>${store==='consum'?'Mercadona':'Consum'}: ${euro(packs*p.stores[store==='consum'?'mercadona':'consum'].price)}</small></span></div>`}).join('')||'<p class="muted">Tu menú no tiene ingredientes pendientes.</p>';
$$('[data-pantry]').forEach(s=>s.onchange=()=>{if(s.value==='auto')delete state.pantry[s.dataset.pantry];else state.pantry[s.dataset.pantry]=s.value;savePantry();renderShopping()});renderBuyAssistant();}
function buyItems(){return shoppingItems().filter(p=>shopPacks(p)>0)}
function renderBuyAssistant(){const a=el('shopAssistant');if(state.buyIndex<0){a.hidden=true;return}a.hidden=false;const it=buyItems();if(state.buyIndex>=it.length){a.innerHTML=`<div class="assistant-done"><strong>✓ Lista repasada</strong><p>Los productos no se añadieron automáticamente al carrito. Confirma los artículos en la web del supermercado antes de pagar.</p><button class="button subdued" id="endBuying">Cerrar asistente</button></div>`;el('endBuying').onclick=()=>{state.buyIndex=-1;renderBuyAssistant()};return}
const p=it[state.buyIndex];a.innerHTML=`<div class="assistant-top"><span class="eyebrow">COMPRA GUIADA · ${state.buyIndex+1}/${it.length}</span><button id="exitBuying" class="reset-custom">✕ Cerrar</button></div><h3>${escapeHtml(p.name)}</h3><p>Necesitas <b>${shopPacks(p)} envase(s)</b> de ${fmtQty(p.pack,p.unit)}. El enlace abre ${state.shoppingStore==='consum'?'Consum':'Mercadona'}; si no hay ficha exacta, abre su sección para buscar el producto.</p><div class="assistant-actions"><a class="button primary" href="${escapeHtml(storeUrl(p,state.shoppingStore))}" target="_blank" rel="noopener noreferrer">Abrir ${state.shoppingStore==='consum'?'Consum':'Mercadona'} ↗</a><button class="button subdued" id="nextBuy">Ya lo he añadido / siguiente →</button></div><small>No accedemos a tu cuenta ni añadimos productos a tu cesta.</small>`;
el('exitBuying').onclick=()=>{state.buyIndex=-1;renderBuyAssistant()};el('nextBuy').onclick=()=>{state.buyIndex++;renderBuyAssistant()};}
function copyShoppingList(){const text=['MIGA · Compra semanal · '+(state.shoppingStore==='consum'?'Consum':'Mercadona'),...buyItems().map(p=>`• ${p.name}: ${shopPacks(p)} envase(s) de ${fmtQty(p.pack,p.unit)} · ${euro(shopPacks(p)*p.stores[state.shoppingStore].price)} · ${storeUrl(p,state.shoppingStore)}`), 'Total estimado: '+euro(buyItems().reduce((sum,p)=>sum+shopPacks(p)*p.stores[state.shoppingStore].price,0)), 'Comprueba precios y carrito en la tienda.'].join('\n');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('Lista copiada ✓')).catch(()=>toast('Puedes imprimir la lista.'));else{const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();toast('Lista copiada ✓')}}
function renderPriceTable(){
 const used=new Set(state.recipes.flatMap(r=>r.ingredients.map(i=>i.id)));
 const all=Object.entries(state.prices).sort((a,b)=>a[1].name.localeCompare(b[1].name,'es'));
 const q=(el('priceSearch')?.value||'').trim().toLocaleLowerCase('es');
 const kind=el('priceScope')?.value||'todos';
 const visible=all.filter(([key,p])=>(kind==='todos'||(kind==='recetas'?used.has(key):!used.has(key)))&&(!q||p.name.toLocaleLowerCase('es').includes(q)||key.toLocaleLowerCase('es').includes(q)));
 el('priceCount').textContent=`Mostrando ${visible.length} de ${all.length} productos · ${used.size} de recetas + ${all.length-used.size} extras`;
 el('priceRows').innerHTML=visible.map(([key,p])=>{const m=p.stores.mercadona,c=p.stores.consum;return `<tr><td><b>${escapeHtml(p.name)}</b><small>Formato orientativo ${fmtQty(p.pack,p.unit)}</small>${!used.has(key)?'<span class="price-extra-tag">Disponible como extra</span>':''}</td><td><b>${euro(m.price)}</b>${statusBadge(m.status)}</td><td><b>${euro(c.price)}</b>${statusBadge(c.status)}</td><td>${retailerLinks(p)}<small class="source-info">${storeKind(p,'mercadona')!=='producto'||storeKind(p,'consum')!=='producto'?'⌕ Algunas referencias abren la categoría/tienda.':''}</small><small class="source-info">${m.date?'Mercadona: '+m.date+' · ':''}${c.date?'Consum: '+c.date:''}</small></td></tr>`}).join('')||'<tr><td colspan="4" class="price-empty">No hay alimentos que coincidan con tu búsqueda.</td></tr>';
}

async function renderAdmin(){if(state.user?.role!=='admin')return;el('adminContent').innerHTML='<p>Cargando registros…</p>';try{const data=await api('/api/admin');el('adminContent').innerHTML=`<div class="admin-stats"><div><small>PERSONAS REGISTRADAS</small><strong>${data.users.length}</strong></div><div><small>RESEÑAS PUBLICADAS</small><strong>${data.reviews.length}</strong></div><div><small>RECETAS</small><strong>${state.recipes.length}</strong></div></div><h2>Usuarios registrados</h2><div class="price-table-wrap"><table class="price-table"><thead><tr><th>Nombre</th><th>Correo electrónico</th><th>Alta</th><th>Reseñas</th><th>Permisos</th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${escapeHtml(u.name)}</td><td>${escapeHtml(u.email)}</td><td>${new Date(u.joined_at).toLocaleDateString('es-ES')}</td><td>${u.reviews_count}</td><td>${u.role==='admin'?'Administrador':'Usuario'}</td></tr>`).join('')}</tbody></table></div><h2 class="admin-subtitle">Últimas reseñas</h2><div class="admin-reviews">${data.reviews.length?data.reviews.map(r=>`<article class="review"><div><b>${escapeHtml(r.name)} · ${escapeHtml(recipe(r.recipe_id)?.title||'Receta')}</b><span>${'★'.repeat(r.rating)}</span></div><p>${escapeHtml(r.comment)}</p><small>${new Date(r.created_at).toLocaleDateString('es-ES')}</small></article>`).join(''):'Aún no hay reseñas.'}</div>`}catch(e){el('adminContent').textContent=e.message}}
function bind(){document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){e.preventDefault();navigate(b.dataset.page)}const a=e.target.closest('[data-open]');if(a){e.preventDefault();openRecipe(a.dataset.open)}const f=e.target.closest('[data-favorite]');if(f){e.preventDefault();toggleFav(Number(f.dataset.favorite))}const c=e.target.closest('[data-close]');if(c)closeModal(c.dataset.close)});
el('accountButton').onclick=()=>openAuth('login');el('search').oninput=e=>{state.search=e.target.value;renderCards()};el('sort').onchange=e=>{state.sort=e.target.value;renderCards()};el('favoritesOnly').onchange=e=>{state.onlyFav=e.target.checked;renderCards()};$$('[data-category]').forEach(btn=>btn.onclick=()=>{state.cat=btn.dataset.category;$$('[data-category]').forEach(b=>b.classList.toggle('active',b===btn));renderCards()});if(el('heroExplore'))el('heroExplore').onclick=()=>el('recetas').scrollIntoView({behavior:'smooth'});el('generatePlan').onclick=makePlan;el('seeShopping').onclick=()=>navigate('compra');el('savePlan').onclick=async()=>{if(!state.user){toast('Inicia sesión para guardar tu menú.');openAuth('login');return}if(!state.plan)return;try{await api('/api/plan',{ids:state.plan.ids,servings:state.plan.servings,budget:Number(state.plan.budget||30),category:state.plan.category||'todos',store:state.plan.store||'consum'});toast('Menú guardado en tu cuenta ✓')}catch(e){toast(e.message)}};el('printList').onclick=()=>window.print();el('shoppingStore').onchange=e=>{state.shoppingStore=e.target.value;state.buyIndex=-1;renderShopping()};el('clearPantry').onclick=()=>{state.pantry={};savePantry();renderShopping()};el('copyList').onclick=copyShoppingList;el('beginBuying').onclick=()=>{if(!buyItems().length)return toast('No necesitas comprar más envases.');state.buyIndex=0;renderBuyAssistant();el('shopAssistant').scrollIntoView({behavior:'smooth',block:'center'})};el('plateSearch').oninput=()=>renderPlateBuilder();el('plateCategory').onchange=e=>{state.plateType=e.target.value;renderPlateRecommendations()};el('plateStrict').onchange=e=>{state.plateStrict=e.target.checked;renderPlateRecommendations()};el('plateReset').onclick=()=>{state.plateFromFridge=false;state.plateIngredients.clear();el('plateSearch').value='';renderPlateBuilder()};el('mobileMenu').onclick=()=>document.body.classList.toggle('menu-open');document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!el('recipeLayer').hidden)closeModal('recipe');if(!el('authLayer').hidden)closeModal('auth')}})}
bind();setupImageFallback(document);initialize();

// Filtro del catálogo completo de precios.
["priceSearch","priceScope"].forEach(id=>{const ctrl=el(id);if(ctrl)ctrl.addEventListener(id==="priceSearch"?"input":"change",renderPriceTable)});
